const times = Array.from({ length: 19 }, (_, i) => `${String(8 + Math.floor(i / 2)).padStart(2, "0")}:${i % 2 ? "30" : "00"}`);
const money = (n: number) => `$${new Intl.NumberFormat("es-AR").format(n)}`;

function Avatar({ initials, color, size = "md" }: { initials: string; color: string; size?: "sm" | "md" | "lg" }) { return <span className={`avatar ${color} avatar-${size}`}>{initials}</span>; }
function Badge({ status }: { status: Status }) { const c: Record<Status,string> = { Pendiente: "pending", Confirmada: "confirmed", Atendida: "done", Cancelada: "cancelled", "No asistió": "noshow" }; return <span className={`badge ${c[status]}`}><i />{status}</span>; }
function DemoTag() { return <span className="demo-tag">DEMO</span>; }
const tlClass: Record<Status,string> = { Pendiente:"pending", Confirmada:"confirmed", Atendida:"done", Cancelada:"cancelled", "No asistió":"noshow" };

export default function Home() {
  const [appointments, setAppointments] = useState(initialAppointments);
  const [appointmentsLoaded, setAppointmentsLoaded] = useState(false);
  const [page, setPage] = useState("Turnos de hoy");
  const [patientList, setPatientList] = useState(patients);
  const [date, setDate] = useState(dateKey(today));
  const [doctor, setDoctor] = useState(doctors[0]);
  const [filter, setFilter] = useState("Todos");
  const [query, setQuery] = useState("");
  const [agendaView, setAgendaView] = useState<"tabla"|"timeline">("tabla");
  const [modal, setModal] = useState<"appointment"|"patient"|"cancel"|"profile"|"service"|"clinical"|"cta"|"import"|null>(null);
  const [selected, setSelected] = useState<Appointment | null>(null);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [toast, setToast] = useState("");
  const [busy, setBusy] = useState(false);
  const [navOpen, setNavOpen] = useState(false);
  const [patientSearch, setPatientSearch] = useState("");
  const [waitlist, setWaitlist] = useState<WaitItem[]>([{id:1,name:"Agustina Flores",service:"Consulta clínica",preferred:"16:30"},{id:2,name:"Nicolás Vega",service:"Control general",preferred:""}]);
  const [waitSim, setWaitSim] = useState<{phase:"offering"|"accepted";slot:string}|null>(null);
  const waitSimBusy = useRef(false);
  const [tour, setTour] = useState(-1);
  const [tourRect, setTourRect] = useState<DOMRect|null>(null);
  const tourRefs = useRef<Record<string,HTMLElement|null>>({});
  const [reminders, setReminders] = useState(true);
  const [reminderDay, setReminderDay] = useState("1 día antes");
  const [serviceList, setServiceList] = useState(services);
  const [serviceVisible, setServiceVisible] = useState(true);
  const [clinicalTemplates, setClinicalTemplates] = useState<ClinicalTemplate[]>([{id:"motivo",title:"Motivo de consulta"},{id:"observaciones",title:"Observaciones"},{id:"diagnostico",title:"Diagnóstico"},{id:"tratamiento",title:"Tratamiento / receta"},{id:"estudios",title:"Estudios solicitados"}]);
  const [clinicName, setClinicName] = useState("Clínica Santa Clara");
  const [welcomeStep, setWelcomeStep] = useState(0);

  useEffect(() => { try { const saved = localStorage.getItem("trinodo-demo-appointments"); if (saved) setAppointments(JSON.parse(saved)); } catch {} finally { setAppointmentsLoaded(true); } }, []);
  useEffect(() => { try { const saved = localStorage.getItem("trinodo-demo-clinical-templates"); if (saved) setClinicalTemplates(JSON.parse(saved)); } catch {} }, []);
  useEffect(() => { try { const n = localStorage.getItem("trinodo-demo-clinic-name"); if (n && n.trim()) setClinicName(n); if (!localStorage.getItem("trinodo-demo-welcome-seen")) setWelcomeStep(1); } catch {} }, []);
  useEffect(() => { try { if (localStorage.getItem("trinodo-demo-waitsim-seen")) return; const t = window.setTimeout(()=>{try{localStorage.setItem("trinodo-demo-waitsim-seen","1")}catch{}simulateWaitFill();},16000); return ()=>window.clearTimeout(t); } catch {} }, []);
  useEffect(() => {
    if (tour < 0 || !tourSteps[tour]) { setTourRect(null); return; }
    const st = tourSteps[tour];
    if (st.page && page !== st.page) setPage(st.page);
    const t0 = window.setTimeout(() => { tourRefs.current[st.key]?.scrollIntoView({ block: "center", behavior: "smooth" }); }, 80);
    const recalc = () => { const target = tourRefs.current[st.key]; setTourRect(target ? target.getBoundingClientRect() : null); };
    recalc();
    const iv = window.setInterval(recalc, 350);
    return () => { window.clearInterval(iv); window.clearTimeout(t0); };
  }, [tour]);
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(""), 3200); return () => clearTimeout(t); } }, [toast]);
  useEffect(() => {
    if (!appointmentsLoaded) return;
    const markMissedAppointments = () => {
      const now = new Date();
      const due = appointments.filter(a => {
        if (a.status !== "Pendiente" && a.status !== "Confirmada") return false;
        const end = new Date(`${a.date}T${a.time}:00`);
        end.setMinutes(end.getMinutes() + a.duration);
        return end <= now;
      });
      if (due.length) {
        const ids = new Set(due.map(a => a.id));
        const next = appointments.map(a => ids.has(a.id) ? { ...a, status: "No asistió" as Status } : a);
        setAppointments(next);
        try { localStorage.setItem("trinodo-demo-appointments", JSON.stringify(next)); } catch {}
      }
    };
    markMissedAppointments();
    const interval = setInterval(markMissedAppointments, 60_000);
    return () => clearInterval(interval);
  }, [appointments, appointmentsLoaded]);

  const dayAppointments = appointments.filter(a => a.date === date);
  const visibleAppointments = useMemo(() => dayAppointments.filter(a => (doctor === doctors[0] || a.doctor === doctor) && (filter === "Todos" || a.status === filter) && (!query || `${a.patient} ${a.doctor} ${a.service}`.toLowerCase().includes(query.toLowerCase()))).sort((a,b) => a.time.localeCompare(b.time)), [appointments, date, doctor, filter, query]);
  const currentPatients = useMemo(() => patientList.filter(p => !patientSearch || `${p.name} ${p.email} ${p.phone}`.toLowerCase().includes(patientSearch.toLowerCase())), [patientList, patientSearch]);
  const countToday = dayAppointments.length;
  const waiting = dayAppointments.filter(a => a.status === "Pendiente").length;
  const collected = dayAppointments.filter(a => a.payment === "Pagado").reduce((s,a) => s+a.amount,0);
  const totalExpected = dayAppointments.reduce((s,a) => s+a.amount,0);
  const confirmedCount = dayAppointments.filter(a=>a.status==="Confirmada"||a.status==="Atendida").length;
  const attendedCount = dayAppointments.filter(a=>a.status==="Atendida").length;
  const confirmPct = countToday ? Math.round(confirmedCount/countToday*100) : 0;
  const savedMins = confirmedCount*2 + attendedCount*2 + waitlist.length*10;
  const savedLabel = savedMins>=60 ? `${Math.floor(savedMins/60)}h ${String(savedMins%60).padStart(2,"0")}m` : `${savedMins} min`;

  function updateStore(next: Appointment[]) { setAppointments(next); try { localStorage.setItem("trinodo-demo-appointments", JSON.stringify(next)); } catch {} }
  function updateClinicalTemplates(next: ClinicalTemplate[]) { setClinicalTemplates(next); try { localStorage.setItem("trinodo-demo-clinical-templates", JSON.stringify(next)); } catch {} }
  function notify(message: string) { setToast(message); }
  function finishWelcome(target?: string) { setWelcomeStep(0); try { localStorage.setItem("trinodo-demo-welcome-seen", "1"); if (!localStorage.getItem("trinodo-demo-tour-seen")) window.setTimeout(()=>setTour(0), 450); } catch {} if (target) setPage(target); }
  function endTour() { setTour(-1); try { localStorage.setItem("trinodo-demo-tour-seen", "1"); } catch {} }
  function simulateWaitFill() {
    if (waitSimBusy.current || waitlist.length===0) return;
    waitSimBusy.current = true;
    const first = waitlist[0];
    const svc = serviceList.find(s=>s.name===first.service) || serviceList[0];
    const doc = svc.doctor;
    const taken = new Set(appointments.filter(a=>a.date===dateKey(today)&&a.doctor===doc&&a.status!=="Cancelada").map(a=>a.time));
    const slot = first.preferred && !taken.has(first.preferred) ? first.preferred : (times.filter(t=>t>="14:00").find(t=>!taken.has(t)) || "17:30");
    setWaitSim({phase:"offering",slot});
    window.setTimeout(()=>setWaitSim({phase:"accepted",slot}), 2600);
    window.setTimeout(()=>{
      const ap: Appointment = { id: Date.now(), patient: first.name, initials: first.name.split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase(), color: "mint", email: "", phone: "", service: svc.name, doctor: doc, time: slot, duration: svc.duration, status: "Confirmada", payment: "Pendiente", amount: svc.price, date: dateKey(today) };
      setAppointments(prev => { const next=[...prev, ap]; try{localStorage.setItem("trinodo-demo-appointments",JSON.stringify(next))}catch{} return next; });
      setWaitlist(prev => prev.filter(x=>x.id!==first.id));
      setWaitSim(null);
      waitSimBusy.current = false;
    }, 5400);
  }
  function changeStatus(a: Appointment, status: Status) { const next = appointments.map(item => item.id === a.id ? { ...item, status } : item); updateStore(next); notify(status === "Confirmada" ? `Turno confirmado. Email enviado a ${a.email}` : status === "Atendida" ? "Consulta marcada como atendida" : status === "No asistió" ? "Inasistencia registrada en el historial" : "Estado actualizado"); }
  function markPaid(a: Appointment) { updateStore(appointments.map(item => item.id === a.id ? { ...item, payment: "Pagado" } : item)); notify("Pago registrado para esta cita"); }
  function exportCsv() { const rows = [["Fecha","Hora","Paciente","Profesional","Servicio","Estado","Pago","Monto"], ...visibleAppointments.map(a => [a.date,a.time,a.patient,a.doctor,a.service,a.status,a.payment,String(a.amount)])]; const csv = rows.map(r=>r.map(x=>`"${x.replaceAll('"','""')}"`).join(",")).join("\n"); const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"})); link.download = `agenda-${date}.csv`; link.click(); URL.revokeObjectURL(link.href); notify("Listado CSV descargado"); }
  function navigateDay(offset: number) { const d = new Date(`${date}T12:00:00`); d.setDate(d.getDate()+offset); setDate(dateKey(d)); }

  const navItems = [{ label: "Turnos de hoy", icon: LayoutDashboard }, { label: "Agenda", icon: CalendarDays }, { label: "Pacientes", icon: Users }, { label: "Profesionales", icon: Stethoscope }, { label: "Servicios", icon: FileText }, { label: "Reserva online", icon: Globe }, { label: "Notas clínicas", icon: FileText }, { label: "Media", icon: ImagePlus }, { label: "Pagos", icon: Wallet }];
  const formatted = new Date(`${date}T12:00:00`).toLocaleDateString("es-AR", { weekday: "long", day: "numeric", month: "long" });
  const clinicInitials = clinicName.split(" ").filter(Boolean).slice(0, 2).map(w => w[0]).join("").toUpperCase() || "CS";
  const tourSteps = [
    { key: "stats", title: "El día de tu clínica, de un vistazo", text: "Turnos, confirmaciones y plata cobrada. Todo calculado con los datos de tu agenda.", page: "Agenda" },
    { key: "wait", title: "La lista de espera llena los huecos", text: "Cuando se libera un turno, la app se lo ofrece sola al primero de la fila. Probá «Simular hueco liberado».", page: "Agenda" },
    { key: "rem", title: "Recordatorios que evitan ausencias", text: "Por email, automáticos. Tus pacientes confirman sin llamar a recepción.", page: "Agenda" },
    { key: "export", title: "Tus datos, siempre tuyos", text: "Exportá la agenda a CSV o PDF cuando quieras. Nada queda atrapado en el sistema.", page: "Agenda" },
    { key: "cta", title: "¿Te gusta lo que viste?", text: "Este mismo sistema puede correr con los datos de tu clínica. Pedilo cuando quieras.", page: "" },
  ];

  return <main className="app-shell">
    <aside className={`sidebar ${navOpen ? "mobile-open" : ""}`}>
      <div className="brand"><div className="brand-mark"><HeartPulse size={21}/></div><div><strong>clinica<span>.</span></strong><small>TRINODO LABS</small></div><button className="mobile-close icon-button" onClick={()=>setNavOpen(false)}><X size={18}/></button></div>
      <div className="workspace"><div className="clinic-logo">{clinicInitials}</div><div className="clinic-meta"><strong>{clinicName}</strong><small>Consultorio privado</small></div><ChevronDown size={15} className="muted"/></div>
      <div className="nav-caption">MENU PRINCIPAL</div>
      <nav>{navItems.map(item=><button key={item.label} onClick={()=>{setPage(item.label);setNavOpen(false);}} className={`nav-item ${page===item.label?"active":""}`}><item.icon size={18}/><span>{item.label}</span>{item.label==="Agenda"&&<span className="nav-count">{countToday}</span>}</button>)}</nav>
      <div className="sidebar-spacer"/>
      <div className="cta-card" ref={el=>{tourRefs.current["cta"]=el;}}><div className="cta-icon"><Sparkles size={16}/></div><strong>¿Te gusta lo que viste?</strong><p>Llevá este sistema a tu consultorio.</p><button onClick={()=>setModal("cta")}>Quiero este sistema <ArrowUpRight size={14}/></button></div>
      <div className="help-card"><div className="help-icon"><CircleHelp size={18}/></div><strong>¿Primera vez acá?</strong><p>Recorré la demo guiada y descubrí lo que hace por tu clínica.</p><button onClick={()=>setTour(0)}>Ver recorrido de 1 minuto <ArrowUpRight size={14}/></button></div>
      <button className="profile-row" onClick={()=>setModal("profile")}><Avatar initials="MR" color="lavender"/><span><strong>María Rodríguez</strong><small>Recepción · Admin</small></span><MoreHorizontal size={18} className="muted"/></button>
    </aside>
    {navOpen && <button aria-label="Cerrar menú" className="scrim" onClick={()=>setNavOpen(false)}/>}
    <section className="main-column">
      <header className="topbar"><div className="crumb"><button className="menu-toggle icon-button" onClick={()=>setNavOpen(true)}><Menu size={19}/></button><span>{clinicName}</span><ChevronRight size={14}/><strong>{page}</strong></div><div className="top-actions"><div className="demo-pill"><span/> Demo interactiva</div><button className="icon-button notification" onClick={()=>notify("No tenés notificaciones nuevas")}><Bell size={18}/><i/></button><button className="top-avatar" onClick={()=>setModal("profile")}>MR</button></div></header>
      <div className="content">
        {page === "Agenda" || page === "Turnos de hoy" ? <>
          <div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot"/> GESTIÓN DE TURNOS</div><h1>{page === "Agenda" ? "Agenda" : "Turnos de hoy"}</h1><p>Hola, María. Esto es lo que pasa hoy en tu clínica.</p></div><button className="primary-button" onClick={()=>setModal("appointment")}><Plus size={17}/> Nuevo turno</button></div>
          <div className="stats-grid" ref={el=>{tourRefs.current["stats"]=el;}}>
            <div className="stat-card"><div className="stat-head"><span>Citas de hoy</span><span className="stat-icon purple"><CalendarDays size={17}/></span></div><div className="stat-number">{countToday}<span className={`stat-compare ${confirmPct>=60?"positive":"neutral"}`}><ArrowUpRight size={14}/> {confirmPct}%</span></div><div className="stat-foot">confirmados o atendidos, calculado con tus datos</div><div className="mini-bars"><i/><i/><i/><i/><i/><i/><i className="bar-active"/></div></div>
            <div className="stat-card"><div className="stat-head"><span>Pendientes</span><span className="stat-icon amber"><Clock3 size={17}/></span></div><div className="stat-number">{waiting}<span className="stat-compare neutral">por confirmar</span></div><div className="stat-foot">de {countToday} turnos programados</div><div className="progress-track"><i style={{width:`${countToday?waiting/countToday*100:0}%`}}/></div></div>
            <div className="stat-card"><div className="stat-head"><span>Cobrado hoy</span><span className="stat-icon green"><Wallet size={17}/></span></div><div className="stat-number">{money(collected)}</div><div className="stat-foot">de {money(totalExpected)} esperados</div><div className="progress-track green-track"><i style={{width:`${totalExpected?collected/totalExpected*100:0}%`}}/></div></div>
            <div className="stat-card stat-insight"><div className="stat-head"><span>Tu clínica en números</span><span className="stat-icon pink"><Activity size={17}/></span></div><div className="insight-line"><span>Atendidos</span><strong>{dayAppointments.filter(a=>a.status==="Atendida").length}</strong></div><div className="insight-line"><span>Confirmados</span><strong>{dayAppointments.filter(a=>a.status==="Confirmada").length}</strong></div><div className="insight-line"><span>Cancelados / no-show</span><strong>{dayAppointments.filter(a=>a.status==="Cancelada"||a.status==="No asistió").length}</strong></div></div>
          </div>
          <div className="schedule-toolbar"><div className="date-control"><button className="icon-button light" onClick={()=>navigateDay(-1)}><ChevronLeft size={18}/></button><button className="date-label" onClick={()=>setDate(dateKey(today))}><CalendarDays size={16}/><span>{formatted}</span></button><button className="icon-button light" onClick={()=>navigateDay(1)}><ChevronRight size={18}/></button><button className="today-link" onClick={()=>setDate(dateKey(today))}>Hoy</button></div><div className="toolbar-filters"><label className="search-box"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar paciente..."/><kbd>⌘ K</kbd></label><label className="select-wrap"><Stethoscope size={15}/><select value={doctor} onChange={e=>setDoctor(e.target.value)}>{doctors.map(d=><option key={d}>{d}</option>)}</select><ChevronDown size={14}/></label><button className="filter-button" onClick={()=>setFilter(filter==="Todos"?"Pendiente":"Todos")}><SlidersHorizontal size={16}/><span>Estado</span>{filter!=="Todos"&&<i/>}</button><button className="export-button" ref={el=>{tourRefs.current["export"]=el;}} onClick={exportCsv}><Download size={16}/><span>Exportar</span></button><button className="filter-button" onClick={()=>notify("Importá tus turnos desde CSV en tu implementación")}><Upload size={16}/><span>Importar</span></button></div></div>
          <div className="schedule-layout"><section className="appointments-card"><div className="card-title-row"><div><h2>Turnos del día <span className="count-chip">{visibleAppointments.length}</span></h2><p>Gestioná y seguí cada consulta</p></div><div className="view-switch"><button className={agendaView==="tabla"?"on":""} onClick={()=>setAgendaView("tabla")}><ListFilter size={13}/> Tabla</button><button className={agendaView==="timeline"?"on":""} onClick={()=>setAgendaView("timeline")}><CalendarDays size={13}/> Agenda visual</button></div><button className="more-button" onClick={exportCsv}><MoreHorizontal size={19}/></button></div>
            {agendaView==="tabla"?<div className="table-wrap"><table><thead><tr><th>HORA</th><th>PACIENTE</th><th>PROFESIONAL</th><th>ESTADO</th><th>PAGO</th><th/></tr></thead><tbody>
              {visibleAppointments.map(a=><tr key={a.id} className={a.status==="Cancelada"||a.status==="No asistió"?"muted-row":""}><td><span className="time">{a.time}</span><span className="duration">{a.duration} min</span></td><td><button className="patient-cell" onClick={()=>{setSelectedPatient(patientList.find(p=>p.name===a.patient)||null);setModal("patient")}}><Avatar initials={a.initials} color={a.color}/><span><strong>{a.patient}</strong><small>{a.service}</small></span></button></td><td><span className="doctor-cell"><span className="doctor-dot"/>{a.doctor.replace("Dra. ","").replace("Dr. ","")}</span></td><td><Badge status={a.status}/></td><td>{a.payment==="Pagado"?<button className="payment paid" onClick={()=>notify("Este pago ya está registrado")}><Check size={13}/>Pagado</button>:<button className="payment unpaid" onClick={()=>markPaid(a)}>{money(a.amount)} <span>· Pendiente</span></button>}</td><td><AppointmentMenu appointment={a} onClinical={()=>{setSelected(a);setModal("clinical")}} onStatus={(status)=>status==="Cancelada"?(setSelected(a),setModal("cancel")):changeStatus(a,status)} onEdit={()=>{setSelected(a);setModal("appointment")}} onNotify={()=>notify(`Email enviado a ${a.email}`)}/></td></tr>)}
            </tbody></table></div>:<div className="timeline"><div className="tl-gutter"><div className="tl-gutter-head"/><div>{times.map((t,i)=><span key={t} className={i%2?"tl-half":""}>{i%2?"":t}</span>)}</div></div>{doctors.slice(1).map((d,di)=>{const col=visibleAppointments.filter(a=>a.doctor===d);const dim=doctor!==doctors[0]&&doctor!==d;return <div className={`tl-col ${dim?"dim":""}`} key={d}><div className="tl-col-head"><Avatar initials={di===0?"VR":"TH"} color={di===0?"lavender":"mint"}/><div><strong>{d}</strong><small>{col.length} turnos</small></div></div><div className="tl-slots" style={{height:times.length*32}}>{col.map(a=>{const idx=times.indexOf(a.time);if(idx<0)return null;const span=Math.ceil(a.duration/30);return <button key={a.id} className={`tl-block ${tlClass[a.status]}`} style={{top:idx*32,height:span*32-4}} onClick={()=>{const p=patients.find(p=>p.name===a.patient)||null;setSelectedPatient(p);setModal("patient");}}><strong>{a.time} · {a.patient}</strong><small>{a.service} · {money(a.amount)}</small></button>;})}</div></div>;})}</div>}
            {visibleAppointments.length===0&&<div className="empty-state"><div className="empty-icon"><CalendarDays size={22}/></div><h3>{dayAppointments.length===0?"Hoy no hay citas":"No encontramos turnos"}</h3><p>{dayAppointments.length===0?"Cuando agendes un turno, va a aparecer acá.":"Probá cambiar los filtros o la búsqueda."}</p>{dayAppointments.length===0&&<button className="secondary-button" onClick={()=>setModal("appointment")}><Plus size={15}/> Agendar primer turno</button>}</div>}
            <div className="table-footer"><span>Mostrando <strong>{visibleAppointments.length}</strong> de <strong>{dayAppointments.length}</strong> turnos</span><div><button disabled><ChevronLeft size={15}/></button><button className="current-page">1</button><button disabled><ChevronRight size={15}/></button></div></div>
          </section>
          <aside className="right-rail"><section className="rail-card save-card"><div className="rail-heading"><div><h3>Tiempo ahorrado hoy</h3><p>Tareas que la app hizo por vos</p></div><span className="save-badge"><Clock3 size={13}/>{savedLabel}</span></div><div className="save-rows"><span>Confirmaciones automáticas<strong>{confirmedCount*2} min</strong></span><span>Historial y notas al instante<strong>{attendedCount*2} min</strong></span><span>Lista de espera activa<strong>{waitlist.length*10} min</strong></span></div><small className="save-note">Estimación con los datos de tu agenda de hoy</small></section><section className="rail-card"><div className="rail-heading"><div><h3>Profesionales</h3><p>Agenda de hoy</p></div><button onClick={()=>setPage("Profesionales")} className="link-arrow"><ArrowUpRight size={16}/></button></div>{["Dra. Valentina Ríos","Dr. Tomás Herrera"].map((d,i)=>{const number=dayAppointments.filter(a=>a.doctor===d).length;return <button className={`doctor-summary ${doctor===d?"selected":""}`} key={d} onClick={()=>setDoctor(doctor===d?doctors[0]:d)}><Avatar initials={i===0?"VR":"TH"} color={i===0?"lavender":"mint"}/><span className="doc-details"><strong>{d}</strong><small>{i===0?"Clínica médica":"Cardiología"}</small></span><span className="doctor-appointments">{number}<small>turnos</small></span></button>})}<button className="all-doctors" onClick={()=>setDoctor(doctors[0])}>Ver agenda completa <ChevronRight size={14}/></button></section>
            <section className="rail-card waitlist-card" ref={el=>{tourRefs.current["wait"]=el;}}><div className="rail-heading"><div><h3>Lista de espera</h3><p>{waitSim?"Llenando hueco…":`${waitlist.length} pacientes esperando`}</p></div><span className="waitlist-count">{waitlist.length}</span></div>{waitlist.map((w,i)=><div className={`wait-row ${waitSim&&i===0?"offering":""}`} key={w.id}><span className="wait-num">0{i+1}</span><span><strong>{w.name}</strong> · {w.service} · {w.preferred?`${w.preferred} preferido`:"sin horario"}</span><button aria-label={`Quitar ${w.name}`} onClick={()=>{setWaitlist(waitlist.filter(x=>x.id!==w.id));notify("Paciente retirado de la lista de espera")}}><X size={14}/></button></div>)}{waitSim&&waitlist[0]&&<div className={`wait-magic ${waitSim.phase}`}><span className="wait-magic-ic">{waitSim.phase==="offering"?<Clock3 size={13}/>:<Check size={13}/>}</span><div><strong>{waitSim.phase==="offering"?`Se liberó un turno · ${waitSim.slot}`:`¡${waitlist[0].name} aceptó el ${waitSim.slot}!`}</strong><p>{waitSim.phase==="offering"?`Ofreciendo el hueco a ${waitlist[0].name} por email…`:"Turno agendado y confirmado en la agenda"}</p></div></div>}<button className="add-wait" disabled={!!waitSim||waitlist.length===0} onClick={simulateWaitFill}><Zap size={14}/> {waitSim?"Llenando hueco…":"Simular hueco liberado"}</button></section>
            <section className="reminder-card" ref={el=>{tourRefs.current["rem"]=el;}}><div className="reminder-top"><span className="reminder-icon"><Mail size={17}/></span><span className="reminder-toggle"><input aria-label="Activar recordatorios" type="checkbox" checked={reminders} onChange={e=>setReminders(e.target.checked)}/></span></div><strong>Recordatorios por email</strong><p>{reminders?"Confirmación inmediata y recordatorio automático":"Los recordatorios están desactivados"}</p><label className="reminder-select"><select aria-label="Antelación del recordatorio" value={reminderDay} onChange={e=>setReminderDay(e.target.value)}><option>1 día antes</option><option>2 días antes</option><option>3 días antes</option></select><ChevronDown size={13}/></label></section>
          </aside></div>
          <div className="bottom-note"><ShieldCheck size={15}/> Tus datos están protegidos y solo son visibles para el equipo de la clínica.<button onClick={()=>notify("Más información sobre privacidad")}>Más información <ArrowUpRight size={13}/></button><span>Última actualización hace un momento</span></div>
        </> : page === "Notas clínicas" ? <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot"/> CONFIGURACIÓN CLÍNICA</div><h1>Notas clínicas</h1><p>Configurá los apartados reutilizables que el equipo podrá agregar a cada cita.</p></div></div><section className="simple-card clinical-config"><div className="card-title-row"><div><h2>Plantillas de la clínica</h2><p>Están disponibles para todos los profesionales en cada atención.</p></div><button className="primary-button" onClick={()=>{const title=window.prompt("Título del nuevo apartado");if(title?.trim()){if(clinicalTemplates.some(t=>t.title.toLowerCase()===title.trim().toLowerCase())){notify("Ya existe un apartado con ese título");return;}updateClinicalTemplates([...clinicalTemplates,{id:crypto.randomUUID(),title:title.trim()}]);notify("Apartado agregado a las plantillas");}}}><Plus size={16}/> Nuevo apartado</button></div><div className="clinical-template-list">{clinicalTemplates.map((template,i)=><div className="clinical-template-row" key={template.id}><span className="template-index">{String(i+1).padStart(2,"0")}</span><span><strong>{template.title}</strong><small>Campo de texto libre</small></span><button className="icon-button" aria-label={`Eliminar ${template.title}`} onClick={()=>{updateClinicalTemplates(clinicalTemplates.filter(t=>t.id!==template.id));notify("Apartado eliminado de las plantillas");}}><X size={16}/></button></div>)}{clinicalTemplates.length===0&&<div className="empty-state"><h3>Todavía no hay plantillas</h3><p>Agregá un apartado para tenerlo disponible en las consultas.</p></div>}</div></section><div className="bottom-note"><ShieldCheck size={15}/> Las plantillas son compartidas por la clínica. Los datos escritos en una cita quedan guardados en esa cita.<span>Datos de demostración</span></div></> : page === "Pacientes" ? <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot"/> EXPEDIENTES</div><h1>Pacientes</h1><p>Datos de contacto e historial de atención.</p></div><div className="heading-actions"><button className="secondary-button" onClick={()=>setModal("import")}><Upload size={15}/> Importar</button><button className="primary-button" onClick={()=>setModal("patient")}><Plus size={17}/> Nuevo paciente</button></div></div><section className="simple-card"><div className="simple-toolbar"><div className="search-box"><Search size={16}/><input placeholder="Buscar por nombre, email o teléfono..." value={patientSearch} onChange={e=>setPatientSearch(e.target.value)}/></div><button className="export-button" onClick={exportCsv}><Download size={16}/> Exportar</button></div><div className="table-wrap"><table><thead><tr><th>PACIENTE</th><th>CONTACTO</th><th>FECHA DE NACIMIENTO</th><th>VISITAS</th><th>ÚLTIMA CITA</th><th/></tr></thead><tbody>{currentPatients.map(p=><tr key={p.name} onClick={()=>{setSelectedPatient(p);setModal("patient")}} className="click-row"><td><span className="patient-cell"><Avatar initials={p.initials} color={p.color}/><span><strong>{p.name}</strong><small>Expediente #{String(patientList.indexOf(p)+1042)}</small></span></span></td><td><span className="contact-cell">{p.email}<small>{p.phone}</small></span></td><td>{p.birth}</td><td><span className="visit-count">{p.visits} <small>consultas</small></span></td><td>{p.lastVisit}</td><td><ChevronRight size={17} className="muted"/></td></tr>)}</tbody></table></div>{currentPatients.length===0&&<div className="empty-state"><div className="empty-icon"><Users size={22}/></div><h3>No encontramos pacientes</h3><p>Probá con otro nombre, email o teléfono.</p></div>}</section><div className="bottom-note"><ShieldCheck size={15}/> El historial reúne citas, estados y pagos manuales asociados a cada paciente.<span>Datos de demostración</span></div></> : page === "Profesionales" ? <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot"/> EQUIPO MÉDICO</div><h1>Profesionales</h1><p>Agendas, especialidades y disponibilidad.</p></div><div className="heading-actions"><button className="secondary-button" onClick={()=>notify("La importación de profesionales se activa en tu implementación")}><Upload size={15}/> Importar</button><button className="primary-button" onClick={()=>notify("El alta de profesionales se activa en la implementación de tu clínica")}><Plus size={17}/> Agregar profesional</button></div></div><div className="doctor-grid">{[{n:"Dra. Valentina Ríos",s:"Clínica médica",ini:"VR",c:"lavender",hours:"Lun a Vie · 09:00 a 16:00",count:dayAppointments.filter(a=>a.doctor===doctors[1]).length},{n:"Dr. Tomás Herrera",s:"Cardiología",ini:"TH",c:"mint",hours:"Lun a Vie · 09:30 a 17:00",count:dayAppointments.filter(a=>a.doctor===doctors[2]).length}].map(d=><div className="professional-card" key={d.n}><div className="professional-top"><Avatar initials={d.ini} color={d.c} size="lg"/><button className="more-button" onClick={()=>notify("Opciones del profesional") }><MoreHorizontal size={19}/></button></div><h2>{d.n}</h2><p>{d.s}</p><div className="professional-meta"><Clock3 size={15}/>{d.hours}</div><div className="professional-bottom"><span>Turnos de hoy</span><strong>{d.count}</strong><button className="text-button" onClick={()=>{setDoctor(d.n);setPage("Agenda")}}>Ver agenda <ArrowUpRight size={14}/></button></div></div>)}</div><section className="simple-card section-gap"><div className="card-title-row"><div><h2>Disponibilidad de hoy</h2><p>Seleccioná un profesional para filtrar su agenda.</p></div><button className="secondary-button" onClick={()=>setPage("Agenda")}><CalendarDays size={15}/> Abrir agenda</button></div></section></> : page === "Servicios" ? <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot"/> CATÁLOGO DE ATENCIÓN</div><h1>Servicios</h1><p>Consultas y precios definidos por cada profesional.</p></div><button className="primary-button" onClick={()=>setModal("service")}><Plus size={17}/> Nuevo servicio</button></div><div className="catalog-banner"><div className="banner-icon"><Sparkles size={18}/></div><div><strong>Precios claros, desde el primer turno</strong><p>Administrá qué servicios y valores querés mostrar en tu clínica.</p></div><button className="toggle-switch" onClick={()=>setServiceVisible(!serviceVisible)}><span className={serviceVisible?"on":""}/></button></div><div className="service-grid">{serviceList.map(s=><div className="service-card" key={s.name}><div className="service-color" style={{background:s.color}}/><div className="service-card-top"><span className="service-tag">Consulta</span><button className="more-button" onClick={()=>notify(`Editando ${s.name}`)}><MoreHorizontal size={18}/></button></div><h2>{s.name}</h2><div className="service-doctor"><span className="doctor-dot"/>{s.doctor}</div><div className="service-details"><span><Clock3 size={14}/>{s.duration} min</span><strong>{money(s.price)}</strong></div><div className="service-visible"><span className={`visibility-dot ${serviceVisible?"":"off"}`}/>{serviceVisible?"Visible para pacientes":"Oculto para pacientes"}<button onClick={()=>setServiceVisible(!serviceVisible)}>{serviceVisible?"Ocultar":"Mostrar"}</button></div></div>)}</div><div className="bottom-note"><ShieldCheck size={15}/> Los precios son configurables por profesional y no representan cobros integrados.<span>Catálogo de la clínica</span></div></> : page === "Reserva online" ? <ReservaOnline serviceList={serviceList} appointments={appointments} clinicName={clinicName} clinicInitials={clinicInitials} onReserve={ap=>updateStore([...appointments, ap])} setPage={setPage}/> : page === "Media" ? <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot"/> ARCHIVOS Y REPORTES</div><h1>Media</h1><p>Exportá listados y gestioná imágenes asociadas a una ficha.</p></div><button className="primary-button" onClick={exportCsv}><Download size={16}/> Exportar agenda</button></div><div className="media-grid"><section className="simple-card media-panel"><div className="media-panel-icon purple"><Download size={19}/></div><h2>Exportar listados</h2><p>Descargá el listado filtrado de turnos para compartirlo o archivarlo.</p><div className="export-options"><button onClick={exportCsv}><FileText size={18}/><span><strong>Agenda en CSV</strong><small>Ideal para Excel y hojas de cálculo</small></span><Download size={16}/></button><button onClick={()=>window.print()}><FileText size={18}/><span><strong>Guardar como PDF</strong><small>Usá la opción “Guardar como PDF” del navegador</small></span><Download size={16}/></button></div></section><section className="simple-card media-panel"><div className="media-panel-icon amber"><ImagePlus size={19}/></div><h2><DemoTag/> Imágenes de pacientes</h2><p>Las imágenes quedan asociadas a una ficha. Demo visual con archivos locales.</p><label className="upload-drop"><input type="file" accept="image/*" multiple onChange={e=>notify(`${e.target.files?.length||0} imagen(es) seleccionadas para adjuntar`)}/><span className="upload-icon"><Plus size={19}/></span><strong>Hacé clic para seleccionar imágenes</strong><small>JPG, PNG o HEIC · hasta 10 MB por archivo</small></label><div className="privacy-inline"><ShieldCheck size={14}/> Los adjuntos se guardan en la nube en la implementación de tu clínica.</div></section></div><section className="simple-card exports-info"><div className="card-title-row"><div><h2>Actividad reciente</h2><p>Exportaciones de demostración</p></div></div><div className="activity-row"><span className="activity-file"><FileText size={17}/></span><span><strong>agenda-{date}.csv</strong><small>Exportado desde Agenda · hoy</small></span><span className="activity-status"><Check size={13}/> Disponible</span><button className="more-button" onClick={exportCsv}><Download size={16}/></button></div></section></> : page === "Pagos" ? <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot"/> INTEGRACIONES</div><h1>Pagos</h1><p>Conectá el sistema de cobro que ya usa tu clínica.</p></div></div><div className="payment-empty"><div className="empty-icon payment-empty-icon"><Wallet size={23}/></div><span className="optional-tag">SECCIÓN OPCIONAL</span><h2><DemoTag/> Integraciones de pago</h2><p>Esta sección se activa y configura según el sistema de cada clínica. No almacenamos datos de tarjetas ni procesamos pagos desde esta demo.</p><div className="payment-options"><span>Mercado Pago</span><span>Transferencias</span><span>Links de pago</span></div><button className="secondary-button" onClick={()=>notify("La integración de cobros se configura según el sistema de tu clínica.")}><Settings2 size={15}/> Solicitar configuración</button></div><div className="manual-note"><div className="stat-icon green"><Check size={17}/></div><div><strong>Los pagos manuales por cita sí están disponibles</strong><p>Desde la agenda podés marcar un turno como pagado y consultar el monto en el historial del paciente.</p></div><button className="text-button" onClick={()=>setPage("Agenda")}>Ir a la agenda <ArrowUpRight size={14}/></button></div></> : <div className="empty-state"><h3>Sección no disponible</h3></div>}
      </div>
    </section>
    {welcomeStep>0 && <div className="welcome-backdrop"><section className="welcome-card">
      <div className="welcome-dots">{[1,2,3].map(i=><i key={i} className={i===welcomeStep?"on":""}/>)}</div>
      {welcomeStep===1 && <>
        <div className="welcome-icon purple"><HeartPulse size={22}/></div>
        <h2>Bienvenida a Trinodo</h2>
        <p>Este es el sistema que gestiona tu consultorio: <strong>turnos, pacientes, notas clínicas y cobros</strong> en un solo lugar.</p>
        <label className="field welcome-field">¿Cómo se llama tu clínica?<input value={clinicName} onChange={e=>{setClinicName(e.target.value);try{localStorage.setItem("trinodo-demo-clinic-name",e.target.value)}catch{}}} placeholder="Clínica Santa Clara"/></label>
        <p className="welcome-hint">Toda la demo va a usar el nombre de tu lugar.</p>
      </>}
      {welcomeStep===2 && <>
        <div className="welcome-icon green"><Sparkles size={22}/></div>
        <h2>Todo en un solo lugar</h2>
        <div className="welcome-list">
          <div><CalendarDays size={15}/> Agenda que se completa sola con la lista de espera</div>
          <div><Mail size={15}/> Confirmaciones y recordatorios automáticos</div>
          <div><FileText size={15}/> Notas clínicas con plantillas del equipo</div>
          <div><Wallet size={15}/> Cobros por cita y datos exportables siempre</div>
        </div>
      </>}
      {welcomeStep===3 && <>
        <div className="welcome-icon amber"><CalendarDays size={22}/></div>
        <h2>Una agenda sin huecos</h2>
        <p>Tus pacientes <strong>reservan y confirman solos</strong> desde tu link. Vos solo mirás cómo se llena la agenda.</p>
      </>}
      <div className="welcome-actions">
        {welcomeStep>1 && <button className="secondary-button" onClick={()=>setWelcomeStep(welcomeStep-1)}>Atrás</button>}
        <button className="ghost-link" onClick={()=>finishWelcome()}>Saltar</button>
        {welcomeStep<3 ? <button className="primary-button" onClick={()=>setWelcomeStep(welcomeStep+1)}>Siguiente <ArrowUpRight size={14}/></button> : <>
          <button className="secondary-button" onClick={()=>finishWelcome("Reserva online")}>Ver la reserva del paciente</button>
          <button className="primary-button" onClick={()=>finishWelcome()}>Explorar la demo <ArrowUpRight size={14}/></button>
        </>}
      </div>
    </section></div>}
    {tour>=0 && tourSteps[tour] && <><div className="tour-hole" style={tourRect?{top:tourRect.top-7,left:tourRect.left-7,width:tourRect.width+14,height:tourRect.height+14}:{display:"none"}}/><div className="tour-card" style={tourRect?(tourRect.bottom+190<window.innerHeight?{top:tourRect.bottom+12,left:Math.max(16,Math.min(tourRect.left,window.innerWidth-306))}:{bottom:window.innerHeight-tourRect.top+12,left:Math.max(16,Math.min(tourRect.left,window.innerWidth-306))}):{top:"50%",left:"50%",transform:"translate(-50%,-50%)"}}><div className="tour-count">{tour+1} de {tourSteps.length}</div><h4>{tourSteps[tour].title}</h4><p>{tourSteps[tour].text}</p><div className="tour-btns"><button className="ghost-link" onClick={endTour}>Salir</button>{tour>0&&<button className="secondary-button" onClick={()=>setTour(tour-1)}>Atrás</button>}{tour<tourSteps.length-1?<button className="primary-button" onClick={()=>setTour(tour+1)}>Siguiente</button>:<button className="primary-button" onClick={()=>{endTour();notify("¡Eso es todo! Tocá la demo libremente")}}>Terminar</button>}</div></div></>}
    {modal && <Modal key={`${modal}-${selected?.id||"new"}`} type={modal} onClose={()=>setModal(null)} appointments={appointments} updateStore={updateStore} clinicalTemplates={clinicalTemplates} updateClinicalTemplates={updateClinicalTemplates} onOpenClinical={(a)=>{setSelected(a);setModal("clinical")}} notify={notify} busy={busy} setBusy={setBusy} selected={selected} selectedPatient={selectedPatient} setSelectedPatient={setSelectedPatient} serviceList={serviceList} setServiceList={setServiceList} clinicName={clinicName} onImportPatients={(list)=>setPatientList(prev=>[...prev,...list])} waitlist={waitlist} setWaitlist={setWaitlist}/>}
    {toast&&<div className="toast"><span><Check size={15}/></span>{toast}<button onClick={()=>setToast("")}><X size={15}/></button></div>}
  </main>;
}

function AppointmentMenu({ appointment, onClinical, onStatus, onEdit, onNotify }: { appointment: Appointment; onClinical: ()=>void; onStatus: (s: Status)=>void; onEdit: ()=>void; onNotify: ()=>void }) {
  const [open,setOpen]=useState(false);
  return <div className="row-menu"><button className="more-button" onClick={()=>setOpen(!open)}><MoreHorizontal size={18}/></button>{open&&<><button className="menu-dismiss" onClick={()=>setOpen(false)}/><div className="dropdown-menu"><button onClick={()=>{onClinical();setOpen(false)}}><FileText size={14}/> Abrir atención clínica</button><button onClick={()=>{onEdit();setOpen(false)}}><FileText size={14}/> Ver / editar turno</button>{appointment.status==="Pendiente"&&<button onClick={()=>{onStatus("Confirmada");setOpen(false)}}><Check size={14}/> Confirmar turno</button>}{appointment.status==="Confirmada"&&<button onClick={()=>{onStatus("Atendida");setOpen(false)}}><Check size={14}/> Marcar atendido</button>}{appointment.status!=="Cancelada"&&appointment.status!=="No asistió"&&<button onClick={()=>{onStatus("No asistió");setOpen(false)}}><X size={14}/> Marcar no asistió</button>}<button onClick={()=>{onNotify();setOpen(false)}}><Mail size={14}/> Reenviar confirmación</button>{appointment.status!=="Cancelada"&&<button className="danger-action" onClick={()=>{onStatus("Cancelada");setOpen(false)}}><X size={14}/> Cancelar turno</button>}</div></>}</div>;
}

function ReservaOnline({ serviceList, appointments, clinicName, clinicInitials, onReserve, setPage }: { serviceList: typeof services; appointments: Appointment[]; clinicName: string; clinicInitials: string; onReserve: (a: Appointment) => void; setPage: (p: string) => void }) {
  const [svc, setSvc] = useState(serviceList[0]?.name || "");
  const [day, setDay] = useState(dateKey(today));
  const [time, setTime] = useState("");
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [done, setDone] = useState<Appointment | null>(null);
  const days = Array.from({ length: 7 }, (_, i) => { const d = new Date(); d.setDate(d.getDate()+i); return dateKey(d); });
  const doctor = serviceList.find(s=>s.name===svc)?.doctor || "Dra. Valentina Ríos";
  const taken = new Set(appointments.filter(a=>a.date===day&&a.doctor===doctor&&a.status!=="Cancelada").map(a=>a.time));
  const nowTime = new Date().toTimeString().slice(0,5);
  const free = times.filter(t=>!taken.has(t)&&!(day===dateKey(today)&&t<=nowTime));
  const weekday = (d: string) => new Date(`${d}T12:00:00`).toLocaleDateString("es-AR",{weekday:"short"});
  const longDate = (d: string) => new Date(`${d}T12:00:00`).toLocaleDateString("es-AR",{weekday:"long",day:"numeric",month:"long"});
  const slug = clinicName.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"") || "mi-clinica";
  function reserve() { if(!time||!name.trim())return; const s=serviceList.find(x=>x.name===svc)||serviceList[0]; const ap:Appointment={id:Date.now(),patient:name.trim(),initials:name.trim().split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase(),color:"pink",email:"",phone,service:s.name,doctor,duration:s.duration,time,amount:s.price,date:day,status:"Pendiente",payment:"Pendiente"}; onReserve(ap); setDone(ap); }
  return <><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-dot"/> LINK PARA TUS PACIENTES</div><h1>Reserva online</h1><p>Así reservan tus pacientes desde tu link público. Probalo: lo que reserves aparece en tu agenda.</p></div><span className="rsv-url"><Globe size={13}/>reserva.trinodo.app/{slug}</span></div>
  <section className="rsv-wrap"><div className="rsv-frame">
    <div className="rsv-head"><Avatar initials={clinicInitials} color="lavender" size="lg"/><div><strong>{clinicName}</strong><small>Reservá tu turno en 30 segundos</small></div><span className="rsv-chip-live"><i/>En línea</span></div>
    {done ? <div className="rsv-success"><span className="rsv-check"><Check size={22}/></span><h3>¡Listo, {done.patient.split(" ")[0]}!</h3><p>Tu turno quedó reservado:</p><div className="rsv-summary"><strong>{done.service}</strong><span>{done.doctor}</span><span>{longDate(done.date)} · {done.time}</span></div><p className="rsv-send"><Mail size={13}/> Te enviamos la confirmación y el recordatorio por email.</p><div className="rsv-actions"><button className="secondary-button" onClick={()=>{setDone(null);setTime("");setName("");setPhone("");}}>Reservar otro turno</button><button className="primary-button" onClick={()=>setPage("Agenda")}>Verlo en la agenda <ArrowUpRight size={14}/></button></div></div> : <div className="rsv-body">
      <span className="rsv-label">1 · Elegí el servicio</span>
      <div className="rsv-chips">{serviceList.map(s=><button key={s.name} className={s.name===svc?"active":""} onClick={()=>{setSvc(s.name);setTime("");}}>{s.name}<small>{money(s.price)}</small></button>)}</div>
      <span className="rsv-label">2 · Profesional</span>
      <div className="rsv-chips"><button className="active">{doctor}</button></div>
      <span className="rsv-label">3 · Elegí el día</span>
      <div className="rsv-chips rsv-days">{days.map(d=><button key={d} className={d===day?"active":""} onClick={()=>{setDay(d);setTime("");}}>{weekday(d)}<small>{d.slice(8)}/{d.slice(5,7)}</small></button>)}</div>
      <span className="rsv-label">4 · Elegí el horario</span>
      <div className="rsv-times">{free.length?free.map(t=><button key={t} className={t===time?"active":""} onClick={()=>setTime(t)}>{t}</button>):<span className="rsv-empty">No quedan horarios este día. Probá otro.</span>}</div>
      <span className="rsv-label">Tus datos</span>
      <div className="field-row"><label className="field">Nombre y apellido<input value={name} onChange={e=>setName(e.target.value)} placeholder="Ej. Ana Martínez"/></label><label className="field">Teléfono<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+54 9 11 ..."/></label></div>
      <button className="primary-button rsv-cta" disabled={!time||!name.trim()} onClick={reserve}>Confirmar reserva <ArrowUpRight size={14}/></button>
      <small className="rsv-foot"><ShieldCheck size={12}/> Reserva de demostración: no se guardan datos reales.</small>
    </div>}
  </div></section>
  <div className="bottom-note"><ShieldCheck size={15}/> Todo lo que reserves acá aparece al instante en la agenda del personal. Probalo: hacé una reserva y abrí la Agenda.<span>Así se ve el link de tu clínica</span></div></>;
}

function Modal({ type, onClose, appointments, updateStore, notify, busy, setBusy, selected, selectedPatient, setSelectedPatient, serviceList, setServiceList, clinicName, onImportPatients, waitlist, setWaitlist, clinicalTemplates, updateClinicalTemplates, onOpenClinical }: { type: "appointment"|"patient"|"cancel"|"profile"|"service"|"clinical"|"cta"|"import"; onClose: ()=>void; appointments: Appointment[]; updateStore: (a:Appointment[])=>void; notify: (s:string)=>void; busy:boolean; setBusy:(b:boolean)=>void; selected: Appointment|null; selectedPatient:Patient|null; setSelectedPatient:(p:Patient|null)=>void; serviceList:typeof services; setServiceList:(s:typeof services)=>void; clinicName:string; onImportPatients:(list:Patient[])=>void; waitlist:WaitItem[]; setWaitlist:(w:WaitItem[])=>void; clinicalTemplates:ClinicalTemplate[]; updateClinicalTemplates:(t:ClinicalTemplate[])=>void; onOpenClinical:(a:Appointment)=>void }) {
  const [patient,setPatient]=useState(selected?.patient||""); const [email,setEmail]=useState(selected?.email||""); const [doctor,setDoctor]=useState(selected?.doctor||doctors[1]); const [service,setService]=useState(selected?.service||services[0].name); const [date,setDate]=useState(selected?.date||dateKey(today)); const [time,setTime]=useState(selected?.time||"09:00"); const [cancelReason,setCancelReason]=useState(""); const [amount,setAmount]=useState(String(services.find(s=>s.name===service)?.price||18500)); const [phone,setPhone]=useState(""); const [birth,setBirth]=useState(""); const [message,setMessage]=useState(""); const [profileTab,setProfileTab]=useState("Datos generales");
  const [clinicalItems,setClinicalItems]=useState<ClinicalItem[]>(selected?.clinicalItems||[]);
  const selectedService=services.find(s=>s.name===service)||services[0];
  const conflict=appointments.find(a=>a.date===date&&a.doctor===doctor&&a.time===time&&a.id!==selected?.id&&a.status!=="Cancelada");
  const isPast=date<dateKey(today)||(date===dateKey(today)&&time<new Date().toTimeString().slice(0,5));
  const patientHistory=appointments.filter(a=>a.patient===selectedPatient?.name).sort((a,b)=>b.date.localeCompare(a.date)||b.time.localeCompare(a.time));
  function submitAppointment(e:React.FormEvent) { e.preventDefault(); if(conflict){setMessage("Este profesional ya tiene un turno en ese horario. Elegí otro horario.");return;} if(isPast){setMessage("No se pueden agendar turnos en una fecha u hora pasada.");return;} if(!patient.trim()){setMessage("Ingresá el nombre del paciente.");return;} setBusy(true);setMessage("");setTimeout(()=>{const match=patients.find(p=>p.name.toLowerCase()===patient.toLowerCase());const ap:Appointment={id:selected?.id||Date.now(),patient,initials:patient.split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase(),color:match?.color||"blue",email,phone:match?.phone||"",service,doctor,time,duration:selectedService.duration,status:selected?.status||"Pendiente",payment:selected?.payment||"Pendiente",amount:Number(amount)||selectedService.price,date,clinicalItems:selected?.clinicalItems};updateStore(selected?appointments.map(a=>a.id===selected.id?ap:a):[...appointments,ap]);setBusy(false);notify(selected?"Turno actualizado":"Turno creado. Email de confirmación enviado");onClose();},460); }
  function savePatient(e:React.FormEvent) {e.preventDefault();setBusy(true);setTimeout(()=>{setBusy(false);notify("Ficha de paciente actualizada");onClose();},420);}
  function submitCancel(e:React.FormEvent) {e.preventDefault();if(!cancelReason.trim()){setMessage("Indicá el motivo de cancelación para dejar trazabilidad.");return;}updateStore(appointments.map(a=>a.id===selected?.id?{...a,status:"Cancelada",reason:cancelReason}:a));notify("Turno cancelado. El motivo quedó en el historial");onClose();}
  function submitService(e:React.FormEvent) {e.preventDefault();if(!patient.trim())return;setServiceList([...serviceList,{name:patient,doctor,price:Number(amount)||0,duration:30,color:"#7b73dc"}]);notify("Servicio agregado al catálogo");onClose();}
  function addClinicalItem(title?:string) { const value=title?.trim()||window.prompt("Título del apartado");if(!value?.trim())return;setClinicalItems(items=>[...items,{id:crypto.randomUUID(),title:value.trim(),content:""}]); }
  function saveClinical(e:React.FormEvent) {e.preventDefault();if(!selected)return;updateStore(appointments.map(a=>a.id===selected.id?{...a,clinicalItems}:a));notify("Atención clínica guardada en la cita");onClose();}
  function submitCta(e:React.FormEvent) {e.preventDefault();setBusy(true);setTimeout(()=>{setBusy(false);notify("¡Gracias! Te contactamos en menos de 24 horas");onClose();},520);}
  function importDemo() { const nuevos: Patient[] = [{ name:"Renata Silva", initials:"RS", color:"blue", email:"renata.s@email.com", phone:"+54 9 11 4455-8899", birth:"02 ago 1990", visits:0, lastVisit:"Primera visita", balance:0 },{ name:"Damián Ferreyra", initials:"DF", color:"mint", email:"damian.f@email.com", phone:"+54 9 11 4770-2211", birth:"17 dic 1983", visits:0, lastVisit:"Primera visita", balance:0 }]; onImportPatients(nuevos); notify("2 pacientes importados desde la planilla"); onClose(); }
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className={`modal ${type==="patient"&&selectedPatient?"patient-modal":""}`}>
    <div className="modal-header"><div><span className="modal-eyebrow">{type==="appointment"?"AGENDA CLÍNICA":type==="patient"?"FICHA DE PACIENTE":type==="cancel"?"TRAZABILIDAD":type==="service"?"CATÁLOGO DE SERVICIOS":type==="clinical"?"REGISTRO DE ATENCIÓN":type==="cta"?"QUIERO ESTE SISTEMA":"CUENTA"}</span><h2>{type==="appointment"?(selected?"Editar turno":"Nuevo turno"):type==="patient"?(selectedPatient?.name||"Nuevo paciente"):type==="cancel"?"Cancelar turno":type==="service"?"Nuevo servicio":type==="clinical"?"Atención clínica":type==="cta"?"Contacto":"Perfil de usuario"}</h2></div><button className="icon-button" onClick={onClose}><X size={18}/></button></div>
    {type==="appointment"&&<form onSubmit={submitAppointment} className="modal-form"><div className="form-section-title"><span>01</span> Datos del turno</div><label className="field">Nombre del paciente<input autoFocus value={patient} onChange={e=>setPatient(e.target.value)} placeholder="Ej. Ana Martínez" required/></label><div className="field-row"><label className="field">Email de contacto<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="paciente@email.com"/></label><label className="field">Profesional<select value={doctor} onChange={e=>setDoctor(e.target.value)}>{doctors.slice(1).map(d=><option key={d}>{d}</option>)}</select></label></div><div className="field-row"><label className="field">Servicio<select value={service} onChange={e=>{setService(e.target.value);setAmount(String(services.find(s=>s.name===e.target.value)?.price||18500));setDoctor(services.find(s=>s.name===e.target.value)?.doctor||doctor)}}>{serviceList.map(s=><option key={s.name}>{s.name}</option>)}</select></label><label className="field">Monto del pago<input type="number" min="0" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="18500"/></label></div><div className="field-row"><label className="field">Fecha<input type="date" min={dateKey(today)} value={date} onChange={e=>setDate(e.target.value)} required/></label><label className="field">Horario<select value={time} onChange={e=>setTime(e.target.value)}>{times.map(t=><option key={t}>{t}</option>)}</select></label></div>{message&&<div className="form-error"><CircleHelp size={15}/>{message}</div>}{conflict&&<div className="form-error"><CircleHelp size={15}/>Ese horario ya está ocupado por {conflict.patient}.</div>}<div className="modal-info"><Mail size={15}/><span>{selected?"Los cambios se reflejan en la agenda.":"Se enviará una confirmación inmediata por email al guardar."}</span></div><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancelar</button><button disabled={busy} className="primary-button" type="submit">{busy?"Guardando…":selected?"Guardar cambios":"Crear turno"}<ArrowUpRight size={15}/></button></div></form>}
    {type==="clinical"&&selected&&<form onSubmit={saveClinical} className="modal-form clinical-form"><div className="clinical-visit-summary"><Avatar initials={selected.initials} color={selected.color}/><div><strong>{selected.patient}</strong><span>{selected.date} · {selected.time} · {selected.service}</span><small>{selected.doctor}</small></div><Badge status={selected.status}/></div><p className="clinical-helper">Agregá apartados propios o insertá plantillas de la clínica. Podés editar cada título y escribir libremente.</p><div className="clinical-toolbar"><button type="button" className="secondary-button" onClick={()=>addClinicalItem()}><Plus size={15}/> Apartado personalizado</button>{clinicalTemplates.length>0&&<label className="template-picker"><FileText size={14}/><select value="" onChange={e=>{const t=clinicalTemplates.find(item=>item.id===e.target.value);if(t)addClinicalItem(t.title);}}><option value="">Usar plantilla…</option>{clinicalTemplates.map(t=><option value={t.id} key={t.id}>{t.title}</option>)}</select><ChevronDown size={13}/></label>}</div><div className="clinical-items">{clinicalItems.map(item=><article className="clinical-item" key={item.id}><div className="clinical-item-title"><input aria-label="Título del apartado" value={item.title} onChange={e=>setClinicalItems(items=>items.map(i=>i.id===item.id?{...i,title:e.target.value}:i))}/><button type="button" className="icon-button" aria-label={`Quitar ${item.title}`} onClick={()=>setClinicalItems(items=>items.filter(i=>i.id!==item.id))}><X size={15}/></button></div><textarea rows={4} placeholder={`Escribí aquí ${item.title.toLowerCase()}…`} value={item.content} onChange={e=>setClinicalItems(items=>items.map(i=>i.id===item.id?{...i,content:e.target.value}:i))}/></article>)}{clinicalItems.length===0&&<div className="clinical-empty"><FileText size={20}/><strong>Esta cita todavía no tiene notas</strong><span>Agregá un apartado o elegí una plantilla para empezar.</span></div>}</div><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cerrar</button><button className="primary-button" type="submit"><Check size={15}/> Guardar atención</button></div></form>}
    {type==="cancel"&&<form onSubmit={submitCancel} className="modal-form"><div className="cancel-summary"><Avatar initials={selected?.initials||"??"} color={selected?.color||"blue"}/><span><strong>{selected?.patient}</strong><small>{selected?.date} · {selected?.time} · {selected?.doctor}</small></span></div><p className="modal-copy">La cita no se elimina. Queda registrada como cancelada en el historial del paciente.</p><label className="field">Motivo de cancelación<select value={cancelReason} onChange={e=>setCancelReason(e.target.value)}><option value="">Seleccioná un motivo</option><option>El paciente reprogramó</option><option>El paciente canceló</option><option>El profesional no está disponible</option><option>Otro</option></select></label>{cancelReason==="Otro"&&<label className="field">Detalle<input value={message} onChange={e=>setMessage(e.target.value)} placeholder="Escribí el motivo"/></label>}{message&&cancelReason===""&&<div className="form-error">{message}</div>}<div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Volver</button><button className="danger-button" type="submit"><X size={15}/> Cancelar turno</button></div></form>}
    {type==="patient"&&selectedPatient&&<><div className="patient-profile"><Avatar initials={selectedPatient.initials} color={selectedPatient.color} size="lg"/><div><strong>{selectedPatient.email}</strong><span>{selectedPatient.phone}</span><small>Paciente desde {selectedPatient.birth}</small></div><button className="icon-button" onClick={()=>notify("Edición completa de fichas en la versión para tu clínica")}><MoreHorizontal size={18}/></button></div><div className="patient-stats"><div><strong>{selectedPatient.visits}</strong><span>Visitas</span></div><div><strong>{money(patientHistory.filter(a=>a.payment==="Pagado").reduce((s,a)=>s+a.amount,0))}</strong><span>Total abonado</span></div><div><strong className={selectedPatient.balance?"text-amber":""}>{money(selectedPatient.balance)}</strong><span>Pendiente</span></div></div><div className="patient-tabs">{["Historial", "Imágenes", "Datos generales"].map(t=><button key={t} onClick={()=>setProfileTab(t)} className={profileTab===t?"chosen":""}>{t}</button>)}</div>{profileTab==="Historial"?<div className="history-list">{patientHistory.map(a=><div className="history-item" key={a.id}><span className="history-date"><strong>{new Date(`${a.date}T12:00:00`).toLocaleDateString("es-AR",{day:"2-digit",month:"short"})}</strong><small>{a.time}</small></span><span className="history-info"><strong>{a.service}</strong><small>{a.doctor}</small>{a.reason&&<em>Motivo: {a.reason}</em>}{a.clinicalItems?.filter(item=>item.content.trim()).length ? <div className="history-clinical">{a.clinicalItems.filter(item=>item.content.trim()).map(item=><div className="history-clinical-item" key={item.id}><strong>{item.title}</strong><p>{item.content}</p></div>)}<button className="text-button" onClick={()=>onOpenClinical(a)}>Ver / editar atención <ArrowUpRight size={13}/></button></div> : <button className="text-button history-add-note" onClick={()=>onOpenClinical(a)}><Plus size={13}/> Agregar nota clínica</button>}</span><span className="history-payment"><Badge status={a.status}/><small>{a.payment==="Pagado"?`Pagado · ${money(a.amount)}`:`Pendiente · ${money(a.amount)}`}</small></span></div>)}</div>:profileTab==="Imágenes"?<div className="patient-images"><label className="upload-drop"><input type="file" accept="image/*" multiple onChange={e=>notify(`${e.target.files?.length||0} imagen(es) adjuntadas a ${selectedPatient.name}`)}/><span className="upload-icon"><ImagePlus size={18}/></span><strong>Adjuntar imágenes</strong><small>Fotos, radiografías u otros archivos</small></label><div className="privacy-inline"><ShieldCheck size={14}/> Adjuntos de demo. Almacenamiento real requiere Cloudinary.</div></div>:<form onSubmit={savePatient} className="modal-form patient-edit"><div className="field-row"><label className="field">Nombre completo<input defaultValue={selectedPatient.name}/></label><label className="field">Fecha de nacimiento<input type="date"/></label></div><div className="field-row"><label className="field">Email<input defaultValue={selectedPatient.email}/></label><label className="field">Teléfono<input defaultValue={selectedPatient.phone}/></label></div><label className="field">Notas administrativas<textarea rows={3} placeholder="Agregar una nota de gestión (no es historia clínica)..."/></label><div className="modal-actions"><button className="secondary-button" type="button" onClick={onClose}>Cerrar</button><button className="primary-button" type="submit">Guardar cambios</button></div></form>}</>}
    {type==="patient"&&!selectedPatient&&<form onSubmit={savePatient} className="modal-form"><label className="field">Nombre completo<input autoFocus value={patient} onChange={e=>setPatient(e.target.value)} required/></label><div className="field-row"><label className="field">Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label className="field">Teléfono<input value={phone} onChange={e=>setPhone(e.target.value)}/></label></div><label className="field">Fecha de nacimiento<input type="date" value={birth} onChange={e=>setBirth(e.target.value)}/></label><div className="modal-actions"><button className="secondary-button" type="button" onClick={onClose}>Cancelar</button><button className="primary-button" type="submit">Crear ficha</button></div></form>}
    {type==="service"&&<form onSubmit={submitService} className="modal-form"><label className="field">Nombre del servicio<input autoFocus value={patient} onChange={e=>setPatient(e.target.value)} placeholder="Ej. Dermatología" required/></label><div className="field-row"><label className="field">Profesional<select value={doctor} onChange={e=>setDoctor(e.target.value)}>{doctors.slice(1).map(d=><option key={d}>{d}</option>)}</select></label><label className="field">Precio<input type="number" min="0" value={amount} onChange={e=>setAmount(e.target.value)}/></label></div><div className="field"><span className="field-label">Visibilidad</span><button type="button" className="visibility-choice" onClick={()=>notify("Este servicio se mostrará en el catálogo de la clínica")}><Check size={15}/> Visible para pacientes</button></div><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancelar</button><button className="primary-button" type="submit">Guardar servicio</button></div></form>}
    {type==="cta"&&<form onSubmit={submitCta} className="modal-form"><div className="form-section-title"><span>01</span> Tus datos</div><label className="field">Nombre y apellido<input autoFocus required placeholder="Ej. María Rodríguez"/></label><div className="field-row"><label className="field">Email<input type="email" required placeholder="vos@tuclinica.com"/></label><label className="field">Teléfono<input placeholder="+54 9 11 ..."/></label></div><label className="field">Tu clínica o consultorio<input defaultValue={clinicName}/></label><div className="modal-info"><Phone size={15}/><span>Coordinamos una llamada y dejamos la demo corriendo con los datos de tu clínica.</span></div><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancelar</button><button disabled={busy} className="primary-button" type="submit">{busy?"Enviando…":"Quiero que me contacten"}<ArrowUpRight size={15}/></button></div></form>}
    {type==="import"&&<div className="modal-form"><div className="upload-drop import-drop"><span className="upload-icon"><Upload size={19}/></span><strong>Arrastrá tu planilla o hacé clic para elegir el archivo</strong><small>CSV o Excel con nombre, email, teléfono y fecha de nacimiento</small></div><div className="modal-info"><FileText size={15}/><span>En tu implementación mapeamos las columnas de la planilla que ya usás hoy. Probá la importación con datos de ejemplo.</span></div><div className="modal-actions"><button type="button" className="secondary-button" onClick={onClose}>Cancelar</button><button type="button" className="primary-button" onClick={importDemo}><Upload size={15}/> Importar 2 pacientes de ejemplo</button></div></div>}
    {type==="profile"&&<><div className="patient-profile account-profile"><Avatar initials="MR" color="lavender" size="lg"/><div><strong>María Rodríguez</strong><span>maria@clinicasantaclara.com</span><small>Recepción · Administradora</small></div></div><div className="account-options"><button onClick={()=>notify("Tu sesión de demostración está activa")}><ShieldCheck size={16}/><span><strong>Sesión mock</strong><small>Acceso de demostración · Recepción</small></span><Check size={15}/></button><button onClick={()=>notify("Preferencias de cuenta en la versión para tu clínica")}><Settings2 size={16}/><span><strong>Preferencias de cuenta</strong><small>Idioma, notificaciones y seguridad</small></span><ChevronRight size={15}/></button><button onClick={()=>notify("La sesión demo permanece abierta")}><LogOut size={16}/><span><strong>Cerrar sesión</strong><small>Volver a la pantalla de acceso</small></span><ChevronRight size={15}/></button></div></>}
  </section></div>;
}
